-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/crystalWar/The_Fumbling_Friar.lua"]={["Path"]="scripts/quests/crystalWar/The_Fumbling_Friar.lua",["SHA256"]="ab6e78484e108e79045cb63276636de4e4666f52a1a830fdd9d1bec8011d283e",["Text"]="-----------------------------------\n-- The Fumbling Friar\n-- !addquest 7 22\n-- Fondactiont : !pos -95 0 196 164\n-- qm2         : !pos 80 -1 457 89\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_FUMBLING_FRIAR)\n\nquest.reward =\n{\n    item = xi.item.SCROLL_OF_RECALL_PASHH,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasKeyItem(xi.keyItem.BRONZE_RIBBON_OF_SERVICE) and -- TODO: Change to BRASS_RIBBON_OF_SERVICE when Campaign has been added.\n                player:getMainLvl() >= 30\n        end,\n\n        [xi.zone.GARLAIGE_CITADEL_S] =\n        {\n            ['Fondactiont'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(26)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [26] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.GARLAIGE_CITADEL_S] =\n        {\n            ['Fondactiont'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.ORNATE_PACKAGE) then\n                        return quest:progressEvent(28)\n                    else\n                        return quest:event(27)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [28] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.ORNATE_PACKAGE)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.GRAUBERG_S] =\n        {\n            ['qm2'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.ORNATE_PACKAGE) then\n                        quest:keyItem(xi.keyItem.ORNATE_PACKAGE)\n                        return quest:noAction()\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.GARLAIGE_CITADEL_S] =\n        {\n            ['Fondactiont'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(29):replaceDefault()\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/The_Lost_Book.lua"]={["Path"]="scripts/quests/crystalWar/The_Lost_Book.lua",["SHA256"]="ba82e212d4762b54d65a9d19674851606841d66be707aab9f4405d187070914a",["Text"]="-----------------------------------\n-- The Lost Book\n-- !addquest 7 26\n--\n-- MYTHRIL_BEASTCOIN - !additem 749\n-- VELLUM            - !additem 2550\n--\n-- Rhinostery Door South - !pos -1 -4.00 -198 94\n-- Quu Bokye             - !pos -159 16 181 145\n-- Optistery Door        - !pos -57 -5.0 89 94\n-- qm0                   - !pos -141 1 -9 99\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_LOST_BOOK)\n\nquest.reward =\n{\n    item = xi.item.SCROLL_OF_RETRACE,\n}\n\nquest.sections =\n{\n    -- Examine the right Rhinostery door (J-9 of the second map) for a cutscene.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and player:getMainLvl() >= 30 and\n                player:hasKeyItem(xi.keyItem.BRONZE_RIBBON_OF_SERVICE)\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Door_Rhinostery_South'] = quest:progressEvent(143),\n\n            onEventFinish =\n            {\n                [143] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    -- Bring a Mythril Beastcoin and travel to present-day Giddeus and trade Quu Bokye\n    -- a Mythril Beastcoin to obtain a Leather-bound Book.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Door_Rhinostery_South'] = quest:progressEvent(148), -- Optional dialogue\n        },\n\n        [xi.zone.GIDDEUS] =\n        {\n            ['Quu_Bokye'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.MYTHRIL_BEASTCOIN) then\n                        return quest:progressEvent(65)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(64)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [65] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.LEATHER_BOUND_BOOK)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    -- Return to the Rhinostery in Windurst (S), and click the southern door for another cutscene.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Door_Rhinostery_South'] = quest:progressEvent(144),\n\n            onEventFinish =\n            {\n                [144] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n\n    -- Go to the Optistery (F-8 on the first map) of Windurst (S) and examine the door for a cutscene.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Door_Optistery']        = quest:progressEvent(145),\n            ['Door_Rhinostery_South'] = quest:event(150), -- Optional dialogue\n\n            onEventFinish =\n            {\n                [145] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.LEATHER_BOUND_BOOK)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n\n    -- Head to Castle Oztroja (S) and examine the ??? at (G-8) on the first map.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 4 and\n                not player:hasKeyItem(xi.keyItem.LYNX_PELT)\n        end,\n\n        [xi.zone.CASTLE_OZTROJA_S] =\n        {\n            ['_qm0'] =\n            {\n                onTrigger = function(player, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LYNX_PELT)\n                end,\n            },\n        },\n    },\n\n    -- Trade a sheet of Vellum to the Optistery door in Windurst Waters (S).\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 4 and\n                player:hasKeyItem(xi.keyItem.LYNX_PELT)\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Door_Optistery'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, xi.item.SHEET_OF_VELLUM) then\n                        return quest:progressEvent(146)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [146] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    player:delKeyItem(xi.keyItem.LYNX_PELT)\n                    quest:setVar(player, 'Prog', 5)\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                end,\n            },\n        },\n    },\n\n    -- Waited game day\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 5 and\n                quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Door_Optistery'] = quest:progressEvent(147),\n\n            onEventFinish =\n            {\n                [147] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/The_Weekly_Adventurer.lua"]={["Path"]="scripts/quests/crystalWar/The_Weekly_Adventurer.lua",["SHA256"]="c0694fbfc44de4e1de02813996ee0db13d097667d3d4a558808702dc44df452d",["Text"]="-----------------------------------\n-- The Weekly Adventurer\n-----------------------------------\n-- !addquest 7 2\n-- Naiko-Paneiko   : !pos 294.030 -33.443 -28.637 171\n-- Rakula-Motakula : !pos -316.786 -12.448 -118.721 91\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_WEEKLY_ADVENTURER)\n\nquest.reward =\n{\n    exp     = 2000,\n    gil     = 2000,\n    keyItem = xi.keyItem.MAP_OF_FORT_KARUGO_NARUGO,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.CRAWLERS_NEST_S] =\n        {\n            ['Naiko-Paneiko'] =\n            {\n                onTrigger = function(player, npc)\n                    -- Hey there, kid, I'm Naiko-Paneiko, up-and-coming ace journalist\n                    return quest:progressEvent(16)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [16] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.SCOOP_DEDICATED_LINKPEARL)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.CRAWLERS_NEST_S] =\n        {\n            ['Naiko-Paneiko'] =\n            {\n                onTrigger = function(player, npc)\n                    local prog = quest:getVar(player, 'Prog')\n\n                    -- Default or Retry state\n                    if prog == 0 or prog == 4 then\n                        -- What are you doing, kid? Get to the Rolanberry Fields rightaru away!\n                        return quest:progressEvent(21)\n                    elseif prog == 1 then -- Success\n                        -- Oh, there you are, kid. Greataru work!\n                        return quest:progressEvent(19, 171, 1, 2984, 3, 0, 10, 0, 0)\n                    elseif prog == 2 then -- Fail type 1\n                        -- Oooh, look who's back! We got problems, kid? I just don'taru get it.\n                        quest:setVar(player, 'Prog', 4)\n                        return quest:progressEvent(17)\n                    elseif prog == 3 then -- Fail type 2\n                        -- Oooh, look who's back! We got problems, kid? This just doesn't make any sense!\n                        quest:setVar(player, 'Prog', 4)\n                        return quest:progressEvent(18)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [19] = function(player, csid, option, npc)\n                    -- SCOOP_DEDICATED_LINKPEARL is removed silently\n                    player:delKeyItem(xi.keyItem.SCOOP_DEDICATED_LINKPEARL)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.ROLANBERRY_FIELDS_S] =\n        {\n            -- NOTE: Merim-Kurim never interacts with you, despite looking like he does in the CS\n\n            ['Rakula-Motakula'] =\n            {\n                onTrigger = function(player, npc)\n                    local prog = quest:getVar(player, 'Prog')\n\n                    -- NOTE: The quiz answers are: 4-4-5.\n                    if prog == 0 then\n                        -- These are dangerous lands, adventurer. We advise that you distance yourself from here.\n                        return quest:progressEvent(3)\n                    elseif prog == 4 then\n                        -- Oh, it's you again.\n                        return quest:progressEvent(3, 0, 0, 0, 0, 0, 0, 0, 1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3] = function(player, csid, option, npc)\n                    if option == 0 then -- Passed the quiz\n                        quest:setVar(player, 'Prog', 1)\n                    elseif option == 1 then -- Picked wrong category\n                        quest:setVar(player, 'Prog', 2)\n                    elseif option == 2 then -- Reported wrong information\n                        quest:setVar(player, 'Prog', 3)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.CRAWLERS_NEST_S] =\n        {\n            -- Alll rightaru! Let's make the news!\n            ['Naiko-Paneiko'] = quest:event(20):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_BAS_0_The_Fighting_Fourth.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_BAS_0_The_Fighting_Fourth.lua",["SHA256"]="9eb50735611e96faa2d44a8b0dab2f82086b64c468c23d1d60817163aadfc5a6",["Text"]="-----------------------------------\n-- The Fighting Fourth (WOTG Nation Quests - Bastok 0)\n-----------------------------------\n-- !addquest 7 7\n-- Turbulent Storm : !pos 422.461 -48.000 -47.308 175\n-- Adelbrecht      : !pos -325.766 -12.601 -76.977 87\n-- Gebhardt        : !pos 206.299 -20.826 669.125 88\n-- Roderich        : !pos -400.039 39.991 -90.445 88\n-- Barricade       : !pos -514.960 37.979 583.287 88\n-----------------------------------\nlocal marketsID = zones[xi.zone.BASTOK_MARKETS_S]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_FIGHTING_FOURTH)\n\nquest.reward =\n{\n    title = xi.title.FOURTH_DIVISION_SOLDIER,\n}\n\nlocal removeRations = function(player)\n    -- Note the messaging specific to this interaction!\n    player:delKeyItem(xi.keyItem.BATTLE_RATIONS)\n    player:messageSpecial(marketsID.text.ARE_TAKEN_AWAY_FROM_CHAR, xi.keyItem.BATTLE_RATIONS)\nend\n\nlocal returnLetter = function(player)\n    -- Note the messaging specific to this interaction!\n    npcUtil.giveKeyItem(player, xi.keyItem.BLUE_RECOMMENDATION_LETTER, marketsID.text.ITEM_RETURNED_TO_CHAR)\nend\n\nlocal quitQuest = function(player)\n    player:delQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_FIGHTING_FOURTH)\n    quest:cleanup(player)\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n            -- TODO: Conditions to not have a different campaign allegiance?\n        end,\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS_S] =\n        {\n            ['Turbulent_Storm'] =\n            {\n                onTrigger = function(player, npc)\n                    -- TODO: Conditions to not have a different campaign allegiance?\n\n                    local hasLetter  = player:hasKeyItem(xi.keyItem.BLUE_RECOMMENDATION_LETTER)\n                    local hasRations = player:hasKeyItem(xi.keyItem.BATTLE_RATIONS)\n\n                    -- TODO: Verify the check for rations exists on retail\n                    if hasLetter or hasRations then\n                        -- You won't be considered a member of the Fighting Fourth until you take that blue recommendation letter to Bastok...\n                        return quest:event(8)\n                    else\n                        -- Hold it right there. You don't look like one of ours.\n                        return quest:event(7)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [7] = function(player, csid, option, npc)\n                    if option == 0 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.BLUE_RECOMMENDATION_LETTER)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Adelbrecht'] =\n            {\n                onTrigger = function(player, npc)\n                    -- TODO: Conditions to not have a different campaign allegiance?\n\n                    if player:hasKeyItem(xi.keyItem.BLUE_RECOMMENDATION_LETTER) then\n                        -- Greetings, civillian. The Seventh Cohors of the Republican Legion's Fourth Division is currently recruiting new troops.\n                        -- Args (from caps): With recommendation letter\n                        return quest:progressEvent(139, 0, 0)\n                    else\n                        -- Greetings, civillian. The Seventh Cohors of the Republican Legion's Fourth Division is currently recruiting new troops.\n                        -- Args (from caps): Without recommendation letter (after first prompt)\n                        return quest:progressEvent(139, 1, 23)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [139] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:delKeyItem(xi.keyItem.BLUE_RECOMMENDATION_LETTER)\n                        npcUtil.giveKeyItem(player, xi.keyItem.BATTLE_RATIONS)\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Adelbrecht'] =\n            {\n                onTrigger = function(player, npc)\n                    local prog = quest:getVar(player, 'Prog')\n\n                    if prog == 0 then\n                        -- I thought you didn't have any questions!\n                        return quest:event(140)\n                    elseif prog == 1 then\n                        -- Good work, rookie. You've passed the test with flying colors! ...Or at least that's what I'd say...\n                        return quest:event(141)\n                    elseif prog == 2 then\n                        -- I heard the news about the ambush.\n                        return quest:event(142)\n                    elseif prog == 3 then\n                        -- Welcome back, rookie. I read the praefectus's report.\n                        return quest:progressEvent(143)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [140] = function(player, csid, option, npc)\n                    if option == 1 then\n                        removeRations(player)\n                        returnLetter(player)\n                        quitQuest(player)\n                    end\n                end,\n\n                [141] = function(player, csid, option, npc)\n                    if option == 1 then\n                        returnLetter(player)\n                        quitQuest(player)\n                    end\n                end,\n\n                [142] = function(player, csid, option, npc)\n                    if option == 1 then\n                        returnLetter(player)\n                        quitQuest(player)\n                    end\n                end,\n\n                [143] = function(player, csid, option, npc)\n                    local hasNoAllegiance = player:getCampaignAllegiance() == 0\n\n                    if\n                        hasNoAllegiance and\n                        not npcUtil.giveItem(player, xi.item.SPRINTERS_SHOES)\n                    then\n                        return\n                    end\n\n                    if quest:complete(player) then\n                        if hasNoAllegiance then\n                            npcUtil.giveKeyItem(player, xi.keyItem.BRONZE_RIBBON_OF_SERVICE)\n                        end\n\n                        player:setCampaignAllegiance(2)\n                        player:messageSpecial(marketsID.text.NOW_ALLIED_WITH, 2)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.NORTH_GUSTABERG_S] =\n        {\n            ['Gebhardt'] =\n            {\n                onTrigger = function(player, npc)\n                    local prog = quest:getVar(player, 'Prog')\n\n                    if prog == 0 then\n                        -- Rations!? Hand those over, rookie!\n                        return quest:progressEvent(102)\n                    elseif prog == 1 then\n                        return quest:event(103) -- Reminder\n                    elseif prog == 2 then\n                        -- Those turtlebacks intercepted the communication!?\n                        return quest:event(107)\n                    elseif prog == 3 then\n                        -- Thanks to your diligence, the Republic is safe for another day.\n                        return quest:event(108)\n                    end\n                end,\n            },\n\n            ['Roderich'] =\n            {\n                onTrigger = function(player, npc)\n                    local prog = quest:getVar(player, 'Prog')\n\n                    if prog == 1 then\n                        -- Centurion Gebhardt asked you to come all the way here...?\n                        return quest:progressEvent(104)\n                    elseif prog == 2 then\n                        return quest:event(105) -- Reminder\n                    elseif prog == 3 then\n                        -- I just heard the report!\n                        return quest:event(109)\n                    end\n                end,\n            },\n\n            ['Barricade'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        -- Stop right there! I think you have something of mine!\n                        return quest:progressEvent(106)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [102] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.BATTLE_RATIONS) -- TODO: Confirm on retail that these are actually taken, there's no message\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [104] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [106] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        -- TODO: Are these new default texts forever, or only as long as you have this campaign allegiance?\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS_S] =\n        {\n            -- I heard about the news, recruit.\n            ['Turbulent_Storm'] = quest:event(9):replaceDefault(),\n        },\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            -- What are you doing soldier?\n            ['Adelbrecht'] = quest:event(162):replaceDefault(),\n        },\n\n        [xi.zone.NORTH_GUSTABERG_S] =\n        {\n            -- Thanks to your diligence, the Republic is safe for another day.\n            ['Gebhardt'] = quest:event(108):replaceDefault(),\n\n            -- I just heard the report!\n            ['Roderich'] = quest:event(109):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_BAS_10_What_Price_Loyalty.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_BAS_10_What_Price_Loyalty.lua",["SHA256"]="896d0535f23c41ee43ed11f50fb3953a39cc3f0a13062a0fba978b9e8a15115d",["Text"]="-----------------------------------\n-- What Price Loyalty (WOTG Nation Quests - Bastok 10)\n-----------------------------------\n-- !addquest 7 50\n-- Gentle Tiger      : !pos -203.932 -9.998 2.237 87\n-- Roderich          : !pos -400.039 40.004 -90.445 88\n-- Forbidding Portal : !pos 320.000 -10.835 158.699 137\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.WHAT_PRICE_LOYALTY)\n\nquest.reward =\n{\n    item = xi.item.FOURTH_STAFF,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BENEATH_THE_MASK) and\n                player:getCurrentMission(xi.mission.log_id.WOTG) >= xi.mission.id.wotg.FATE_IN_HAZE\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:progressEvent(348),\n\n            onEventFinish =\n            {\n                [348] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.SACK_OF_VICTUALS)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                vars.Prog == 0 and\n                player:hasKeyItem(xi.keyItem.SACK_OF_VICTUALS)\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(354),\n        },\n\n        [xi.zone.NORTH_GUSTABERG_S] =\n        {\n            ['Roderich'] = quest:progressEvent(10),\n\n            onEventFinish =\n            {\n                [10] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                    player:delKeyItem(xi.keyItem.SACK_OF_VICTUALS)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.NORTH_GUSTABERG_S] =\n        {\n            ['Roderich'] = quest:event(11),\n        },\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:progressEvent(349),\n\n            onEventFinish =\n            {\n                [349] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(355),\n        },\n\n        [xi.zone.XARCABARD_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 8\n            end,\n\n            onEventFinish =\n            {\n                [8] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                    npcUtil.giveKeyItem(player, xi.keyItem.COMMANDERS_ENDORSEMENT)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                vars.Prog == 3 and\n                player:hasKeyItem(xi.keyItem.COMMANDERS_ENDORSEMENT)\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(355),\n        },\n\n        [xi.zone.XARCABARD_S] =\n        {\n            ['Forbidding_Portal'] = quest:progressEvent(9),\n\n            onEventFinish =\n            {\n                [9] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 4\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.COMMANDERS_ENDORSEMENT) then\n                        return quest:event(355)\n                    else\n                        return quest:progressEvent(357)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [357] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.COMMANDERS_ENDORSEMENT)\n                end,\n            },\n        },\n\n        [xi.zone.EVERBLOOM_HOLLOW] =\n        {\n            onEventFinish =\n            {\n                -- What Price Loyalty instance is not implemented currently.\n                [10000] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                    player:setPos(320.000, -10.835, 158.699, 0, xi.zone.XARCABARD_S)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 5\n        end,\n\n        [xi.zone.XARCABARD_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                if prevZone == xi.zone.EVERBLOOM_HOLLOW then\n                    return 10\n                end\n            end,\n\n            onEventFinish =\n            {\n                [10] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 6\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:progressEvent(350),\n\n            onEventFinish =\n            {\n                [350] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(356),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_BAS_11_The_Truth_Lies_Hid.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_BAS_11_The_Truth_Lies_Hid.lua",["SHA256"]="921aeb9cf67884205561701cb6da7385d666801ba41648a5cd943234e23536b1",["Text"]="-----------------------------------\n-- The Truth Lies Hid (WOTG Nation Quests - Bastok 11)\n-----------------------------------\n-- !addquest 7 58\n-- Gentle Tiger    : !pos -203.932 -9.998 2.237 87\n-- Rikke           : !pos -90.120 0.601 86.312 155\n-- Rakke           : !pos -113.722 0.601 -149.880 155\n-- Rokke           : !pos -30.042 0.601 -153.925 155\n-- ??? (qm)        : !pos -384.257 -51.999 -95.783 155\n-- Displaced Block : !pos -264.139 -52.999 82.333 155\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_TRUTH_LIES_HID)\n\nquest.reward =\n{\n    item = xi.item.SANCTUS_ROSARY,\n}\n\nlocal impScenarios =\n{\n    -- Scenario A\n    {\n        honestImp  = 2,\n        statements =\n        {\n            [1] = 1,\n            [2] = 1,\n            [3] = 1,\n        },\n    },\n\n    -- Scenario B\n    {\n        honestImp  = 1,\n        statements =\n        {\n            [1] = 0,\n            [2] = 0,\n            [3] = 0,\n        },\n    },\n\n    -- Scenario C\n    {\n        honestImp  = 3,\n        statements =\n        {\n            [1] = 0,\n            [2] = 2,\n            [3] = 0,\n        },\n    },\n}\n\nlocal impData =\n{\n    [1] =\n    {\n        dayVar     = 'Imp1Day',\n        initial    = 9,\n        reminder   = 19,\n        trade      = 12,\n        selfTrade  = 22,\n        otherTrade = 25,\n    },\n\n    [2] =\n    {\n        dayVar     = 'Imp2Day',\n        initial    = 10,\n        reminder   = 20,\n        trade      = 13,\n        selfTrade  = 23,\n        otherTrade = 26,\n    },\n\n    [3] =\n    {\n        dayVar     = 'Imp3Day',\n        initial    = 11,\n        reminder   = 21,\n        trade      = 14,\n        selfTrade  = 24,\n        otherTrade = 27,\n    },\n}\n\nlocal function getCurrentImpScenario()\n    -- The active scenario rotates by Vana'diel day.\n    return impScenarios[(VanadielUniqueDay() % #impScenarios) + 1]\nend\n\nlocal function setImpTradeState(player, impNumber, isCorrect)\n    quest:setVar(player, 'TradeDay', VanadielUniqueDay())\n    quest:setVar(player, 'TradeImp', impNumber)\n    quest:setVar(player, 'TradeSuccess', isCorrect and 1 or 0)\nend\n\nlocal function handleImpPuzzleTrigger(player, impNumber)\n    local imp = impData[impNumber]\n\n    if quest:getVar(player, 'TradeDay') == VanadielUniqueDay() then\n        local tradeSucceeded = quest:getVar(player, 'TradeSuccess')\n\n        if quest:getVar(player, 'TradeImp') == impNumber then\n            return quest:event(imp.selfTrade, 155, 0, tradeSucceeded)\n        end\n\n        return quest:event(imp.otherTrade, tradeSucceeded)\n    end\n\n    local param3 = getCurrentImpScenario().statements[impNumber]\n\n    if quest:getVar(player, imp.dayVar) == VanadielUniqueDay() then\n        return quest:event(imp.reminder, 155, 0, param3)\n    end\n\n    quest:setVar(player, imp.dayVar, VanadielUniqueDay())\n    return quest:event(imp.initial, 155, 0, param3)\nend\n\nlocal function handleImpTrade(player, impNumber, trade)\n    local imp = impData[impNumber]\n\n    if\n        npcUtil.tradeHasExactly(trade, xi.item.ELIXIR) and\n        quest:getVar(player, 'TradeDay') ~= VanadielUniqueDay()\n    then\n        local isCorrect = getCurrentImpScenario().honestImp == impNumber\n        setImpTradeState(player, impNumber, isCorrect)\n\n        if isCorrect then\n            return quest:progressEvent(imp.trade, 155, 0, 1)\n        end\n\n        return quest:event(imp.trade, 155, 0, 0)\n    end\nend\n\nlocal function handleSolvedImpTrigger(impNumber)\n    local imp = impData[impNumber]\n\n    if getCurrentImpScenario().honestImp == impNumber then\n        return quest:event(imp.selfTrade, 155, 0, 1)\n    end\n\n    return quest:event(imp.otherTrade, 1)\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.WHAT_PRICE_LOYALTY) and\n                player:getCurrentMission(xi.mission.log_id.WOTG) >= xi.mission.id.wotg.ADIEU_LILISETTE\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:progressEvent(211),\n\n            onEventFinish =\n            {\n                [211] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(212),\n        },\n\n        [xi.zone.CASTLE_ZVAHL_BAILEYS_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 12\n            end,\n\n            onEventFinish =\n            {\n                [12] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.CASTLE_ZVAHL_KEEP_S] =\n        {\n            ['Rikke'] =\n            {\n                onTrade = function(player, npc, trade)\n                    return handleImpTrade(player, 1, trade)\n                end,\n\n                onTrigger = function(player, npc)\n                    return handleImpPuzzleTrigger(player, 1)\n                end,\n            },\n\n            ['Rakke'] =\n            {\n                onTrade = function(player, npc, trade)\n                    return handleImpTrade(player, 2, trade)\n                end,\n\n                onTrigger = function(player, npc)\n                    return handleImpPuzzleTrigger(player, 2)\n                end,\n            },\n\n            ['Rokke'] =\n            {\n                onTrade = function(player, npc, trade)\n                    return handleImpTrade(player, 3, trade)\n                end,\n\n                onTrigger = function(player, npc)\n                    return handleImpPuzzleTrigger(player, 3)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [12] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'TradeImp') == 1 and quest:getVar(player, 'TradeSuccess') == 1 then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n\n                [13] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'TradeImp') == 2 and quest:getVar(player, 'TradeSuccess') == 1 then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n\n                [14] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'TradeImp') == 3 and quest:getVar(player, 'TradeSuccess') == 1 then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.CASTLE_ZVAHL_KEEP_S] =\n        {\n            ['Rikke'] =\n            {\n                onTrigger = function(player, npc)\n                    return handleSolvedImpTrigger(1)\n                end,\n            },\n\n            ['Rakke'] =\n            {\n                onTrigger = function(player, npc)\n                    return handleSolvedImpTrigger(2)\n                end,\n            },\n\n            ['Rokke'] =\n            {\n                onTrigger = function(player, npc)\n                    return handleSolvedImpTrigger(3)\n                end,\n            },\n\n            ['qm'] = quest:progressEvent(15),\n\n            onEventFinish =\n            {\n                [15] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3\n        end,\n\n        [xi.zone.CASTLE_ZVAHL_KEEP_S] =\n        {\n            ['Displaced_Block'] = quest:progressEvent(16),\n\n            onEventFinish =\n            {\n                [16] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_BAS_12_Bonds_of_Mythril.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_BAS_12_Bonds_of_Mythril.lua",["SHA256"]="70531cef97a35bb0855adb52f6a20baef114de6391516d1d02bd083156bac5c8",["Text"]="-----------------------------------\n-- Bonds of Mythril (WOTG Nation Quests - Bastok 12)\n-----------------------------------\n-- !addquest 7 59\n-- Gentle Tiger    : !pos -203.932 -9.998 2.237 87\n-- ??? (qm)        : !pos -384.257 -51.999 -95.783 155\n-- Throne Room [S] : !pos -115.849 -8.657 0.000 156\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BONDS_OF_MYTHRIL)\nlocal keepID = zones[xi.zone.CASTLE_ZVAHL_KEEP_S]\n\nquest.reward =\n{\n    item  = xi.item.EXCELSIS_RING,\n    title = xi.title.TEMPERER_OF_MYTHRIL,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_TRUTH_LIES_HID) and\n                player:getCurrentMission(xi.mission.log_id.WOTG) >= xi.mission.id.wotg.ADIEU_LILISETTE\n        end,\n\n        [xi.zone.CASTLE_ZVAHL_BAILEYS_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                if prevZone == xi.zone.CASTLE_ZVAHL_KEEP_S then\n                    return 13\n                end\n            end,\n\n            onEventFinish =\n            {\n                [13] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.CASTLE_ZVAHL_KEEP_S] =\n        {\n            ['qm'] = quest:progressEvent(17),\n\n            onEventFinish =\n            {\n                [17] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.CASTLE_ZVAHL_KEEP_S] =\n        {\n            ['qm'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'ImpKills') >= 4 then\n                        if npcUtil.popFromQM(player, npc, keepID.mob.GARGOUILLE_WARDEN, { hide = 0 }) then\n                            quest:setVar(player, 'ImpKills', 0)\n                        end\n\n                        return quest:messageSpecial(keepID.text.A_SHIVER_RUNS_DOWN)\n                    end\n\n                    return quest:progressEvent(17)\n                end,\n            },\n\n            ['Keep_Imp'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        local impKills = quest:getVar(player, 'ImpKills')\n                        quest:setVar(player, 'ImpKills', math.min(4, impKills + 1))\n                    end\n                end,\n            },\n\n            ['Gargouille_Warden'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.CASTLE_ZVAHL_KEEP_S] =\n        {\n            ['qm'] = quest:progressEvent(18),\n\n            onEventFinish =\n            {\n                [18] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                    npcUtil.giveKeyItem(player, xi.keyItem.ZVAHL_PASSKEY)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                player:hasKeyItem(xi.keyItem.ZVAHL_PASSKEY)\n        end,\n\n        [xi.zone.THRONE_ROOM_S] =\n        {\n            ['_4c1'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(12)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [12] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                -- Bonds of Mythril battlefield is not implemented currently.\n                [32001] = function(player, csid, option, npc)\n                    if\n                        player:getLocalVar('battlefieldWin') == xi.battlefield.id.BONDS_OF_MYTHRIL and\n                        quest:getVar(player, 'Prog') == 4\n                    then\n                        quest:setVar(player, 'Prog', 5)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 5\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(213, 87, 0, 2964, 0)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [213] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                    player:setPos(52.272, -14.000, -0.017, 127, xi.zone.METALWORKS)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 6\n        end,\n\n        [xi.zone.METALWORKS] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 972\n            end,\n\n            onEventFinish =\n            {\n                [972] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 7)\n                    player:setPos(380.062, 0.753, 147.908, 194, xi.zone.NORTH_GUSTABERG_S)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 7\n        end,\n\n        [xi.zone.NORTH_GUSTABERG_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 13\n            end,\n\n            onEventFinish =\n            {\n                [13] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.ZVAHL_PASSKEY)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(214):replaceDefault(),\n        },\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Naji'] = quest:event(971):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_BAS_1_Better_Part_of_Valor.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_BAS_1_Better_Part_of_Valor.lua",["SHA256"]="7cf765c0c42ca063efd16076a4071ad45f6d7378bf34c469c92e2cbe2523196c",["Text"]="-----------------------------------\n-- Better Part of Valor (WOTG Nation Quests - Bastok 1)\n-----------------------------------\n-- !addquest 7 12\n-- Wolfram    : !pos -249 0 88 87\n-- Engelhart  : !pos -79 -4 -123 87\n-- ???        : !pos -232 41 425 88\n-- Leadavox   : !pos 206 -32 316 83\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BETTER_PART_OF_VALOR)\n\nquest.reward =\n{\n    gil     = 10000,\n    keyItem = xi.keyItem.WARNING_LETTER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.wotg.helpers.hasCompletedFirstQuest(player)\n        end,\n\n        [xi.zone.NORTH_GUSTABERG_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                if prevZone == xi.zone.BASTOK_MARKETS_S then\n                    return 1\n                end\n            end,\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.CLUMP_OF_ANIMAL_HAIR)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Engelhart'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(116)\n                    elseif questProgress == 4 then\n                        return quest:progressEvent(118)\n                    else\n                        return quest:event(117)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [116] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                    player:delKeyItem(xi.keyItem.CLUMP_OF_ANIMAL_HAIR)\n                end,\n\n                [118] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.XHIFHUT)\n                        player:needToZone(true)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.NORTH_GUSTABERG_S] =\n        {\n            ['qm1'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(3)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [3] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n\n            ['Solitary_Ant'] = quest:event(2):replaceDefault(),\n        },\n\n        [xi.zone.VUNKERL_INLET_S] =\n        {\n            ['Leadavox'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 2 then\n                        return quest:progressEvent(101)\n                    elseif questProgress == 3 then\n                        return quest:event(102)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 3 and\n                        npcUtil.tradeHasExactly(trade, { { xi.item.GNOLE_CLAW, 1 } })\n                    then\n                        return quest:progressEvent(103)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [101] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [103] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.XHIFHUT)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_BAS_2_Fires_of_Discontent.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_BAS_2_Fires_of_Discontent.lua",["SHA256"]="ec2cc24c6c5e8d976ecdc8f2c159eee5722d28912a1a974ec55ddfe5c944daf7",["Text"]="-----------------------------------\n-- Fires of Discontent (WOTG Nation Quests - Bastok 2)\n-----------------------------------\n-- !addquest 7 13\n-- Engelhart    : !pos -80.085 -4.425 -125.327 87\n-- Pagdako      : !pos -202.080 -6.000 -93.928 87\n-- Iron Eater   : !pos 92.936 -19.532 1.814 237\n-- qm5          : !pos 259.793 33.192 515.257 89\n-- Gentle Tiger : !pos -203.932 -9.998 2.237 87\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.FIRES_OF_DISCONTENT)\n\nquest.reward =\n{\n    gil = 10000,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BETTER_PART_OF_VALOR)\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Engelhart'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(120)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [120] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Engelhart'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress < 2 then\n                        return quest:event(121)\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(124)\n                    elseif questProgress == 3 then\n                        return quest:event(125)\n                    elseif questProgress == 4 then\n                        return quest:progressEvent(126)\n                    elseif questProgress == 5 then\n                        return quest:event(127)\n                    elseif questProgress == 6 then\n                        return quest:progressEvent(164)\n                    end\n                end,\n            },\n\n            ['Pagdako'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(122)\n                    else\n                        return quest:event(123)\n                    end\n                end,\n            },\n\n            ['Gentle_Tiger'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 5 then\n                        return quest:progressEvent(160)\n                    else\n                        return quest:event(161)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [122] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [124] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [126] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n\n                [160] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                end,\n\n                [164] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.METALWORKS] =\n        {\n            ['Iron_Eater'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(956)\n                    else\n                        return quest:event(957)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [956] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.GRAUBERG_S] =\n        {\n            ['qm5'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(11)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [11] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Engelhart'] = quest:event(165):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_BAS_3_Light_in_the_Darkness.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_BAS_3_Light_in_the_Darkness.lua",["SHA256"]="f0b002fec1408f4783ecfc38f71f296042411b6f87ab0d5ee44e4ada477152af",["Text"]="-----------------------------------\n-- Light in the Darkness (WOTG Nation Quests - Bastok 3)\n-----------------------------------\n-- !addquest 7 19\n-- Gentle Tiger   : !pos -203.932 -9.998 2.237 87\n-- Pagdako        : !pos -202.080 -6.000 -93.928 87\n-- Blatherix      : !pos -309.824 -11.999 -42.791 87\n-- Engelhart      : !pos -80.085 -4.425 -125.327 87\n-- MINE_SHAFT_KEY : !addkeyitem 961\n-- Corroded Door  : !pos -385.602 21.970 456.359 90\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.LIGHT_IN_THE_DARKNESS)\n\nquest.reward =\n{\n    item = xi.item.ADAMAN_INGOT,\n}\n\nquest.sections =\n{\n    -- Talk to Gentle Tiger at (H-6)\n    -- TODO: 1 day wait after WOTG Mission: Cait Sith\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedMission(xi.mission.log_id.WOTG, xi.mission.id.wotg.BACK_TO_THE_BEGINNING) and -- WotG mission requirement.\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.FIRES_OF_DISCONTENT)    -- WotG nation quest requirement.\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(16)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [16] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Talk to Pagdako at (H-9)\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            -- Reminders\n            ['Gentle_Tiger'] = quest:event(17),\n            ['Engelhart'] = quest:event(18),\n\n            ['Pagdako'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(19)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [19] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    -- Talk to Blatherix at (F-8)\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            -- Reminders\n            ['Gentle_Tiger'] = quest:event(17),\n            ['Engelhart'] = quest:event(18),\n            ['Pagdako'] = quest:event(20),\n\n            ['Blatherix'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(21)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [21] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    -- He asks you to bring him 30 chunks of Goblin Chocolate or 5000 gil to talk.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            -- Reminders\n            ['Gentle_Tiger'] = quest:event(17),\n            ['Engelhart'] = quest:event(18),\n            ['Pagdako'] = quest:event(20),\n\n            ['Blatherix'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(22)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, { { xi.item.CHUNK_OF_GOBLIN_CHOCOLATE, 30 } }) or\n                        npcUtil.tradeHasExactly(trade, { { 'gil', 5000 } })\n                    then\n                        return quest:progressEvent(23)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [23] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MINE_SHAFT_KEY)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n\n    -- Enter Pashhow Marshlands (S) from Grauberg (S) for a cutscene\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3\n        end,\n\n        [xi.zone.PASHHOW_MARSHLANDS_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                if prevZone == xi.zone.GRAUBERG_S then\n                    return 901\n                end\n            end,\n\n            onEventFinish =\n            {\n                [901] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            -- Reminders\n            ['Gentle_Tiger'] = quest:event(17),\n            ['Engelhart'] = quest:event(18),\n            ['Pagdako'] = quest:event(20),\n            ['Blatherix'] = quest:event(24),\n        },\n    },\n\n    -- Check the Corroded Door at (F-5) in Pashhow Marshlands (S) to enter the battlefield for Light in the Darkness\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 4\n        end,\n\n        -- Instance entry handled in instance script\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            -- Reminders\n            ['Gentle_Tiger'] = quest:event(17),\n            ['Engelhart'] = quest:event(18),\n            ['Pagdako'] = quest:event(20),\n            ['Blatherix'] = quest:event(24),\n        },\n    },\n\n    -- Enter Pashhow Marshlands (S) the instance for a cutscene\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 5\n        end,\n\n        [xi.zone.PASHHOW_MARSHLANDS_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 902\n            end,\n\n            onEventFinish =\n            {\n                [902] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                end,\n            },\n        },\n    },\n\n    -- Once you have beaten the Quadav in Ruhotz Silvermines, talk to Gentle Tiger for the final cutscene\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 6\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            -- Reminders\n            ['Engelhart'] = quest:event(18),\n            ['Pagdako'] = quest:event(20),\n            ['Blatherix'] = quest:event(24),\n\n            ['Gentle_Tiger'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(27)\n                end,\n            },\n\n            -- TODO: Before new day for next quest: cs 28\n\n            onEventFinish =\n            {\n                [27] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.quest.setVar(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BURDEN_OF_SUSPICION, 'Timer', VanadielUniqueDay() + 1)\n                        xi.quest.setMustZone(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BURDEN_OF_SUSPICION)\n                    end\n                end,\n            },\n        },\n    },\n\n    -- Upon failure, a new key is needed. Blatherix will ask for 10 chunks of Goblin Chocolate or 1000 gil to give you one\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 7\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            -- Reminders\n            ['Gentle_Tiger'] = quest:event(17),\n            ['Engelhart'] = quest:event(18),\n            ['Pagdako'] = quest:event(20),\n\n            ['Blatherix'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(25)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, { { xi.item.CHUNK_OF_GOBLIN_CHOCOLATE, 10 } }) or\n                        npcUtil.tradeHasExactly(trade, { { 'gil', 1000 } })\n                    then\n                        return quest:progressEvent(23)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [23] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    npcUtil.giveKeyItem(player, xi.keyItem.MINE_SHAFT_KEY)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_BAS_4_Burden_of_Suspicion.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_BAS_4_Burden_of_Suspicion.lua",["SHA256"]="64697997e6e1032245bf575972e27098342f8fe086ee59523de0fd574aa2cdf5",["Text"]="-----------------------------------\n-- Burden of Suspicion (WOTG Nation Quests - Bastok 4)\n-----------------------------------\n-- !addquest 7 20\n-- Gentle Tiger : !pos -203 -9 0 87\n-- Engelhart    : !pos -79 -4 -123 87\n-- Sarcophagus  : !pos 346 -32 -125 175\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BURDEN_OF_SUSPICION)\n\nquest.reward =\n{\n    title = xi.title.ASSISTANT_DETECTIVE,\n}\n\nquest.sections =\n{\n    -- Talk to Gentle Tiger in Bastok Markets (S)\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.LIGHT_IN_THE_DARKNESS)\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not quest:getMustZone(player) and\n                        quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n                    then\n                        return quest:progressEvent(30)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [30] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    player:delKeyItem(xi.keyItem.WARNING_LETTER)\n                end,\n            },\n        },\n    },\n\n    -- Continue the investigation in Bastok Markets (S) and The Eldieme Necropolis [S]\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:event(28) -- Retail accurate, but odd.\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(34)\n                    else\n                        return quest:event(31)\n                    end\n                end,\n            },\n\n            ['Engelhart'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(32)\n                    elseif questProgress == 2 then\n                        return quest:event(36)\n                    else\n                        return quest:event(33)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [32] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [34] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS_S] =\n        {\n            ['Sarcophagus'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(17)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [17] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_BAS_5_Storm_on_the_Horizon.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_BAS_5_Storm_on_the_Horizon.lua",["SHA256"]="6b91d2198451e326d271c4fdba53cd833b5189ebc02394b532ef2f5ae8300c13",["Text"]="-----------------------------------\n-- Storm on the Horizon (WOTG Nation Quests - Bastok 5)\n-----------------------------------\n-- !addquest 7 35\n-- Blatherix    : !pos -310 -12 -43 87\n-- Gentle Tiger : !pos -203 -9 0 87\n-- Monument     : !pos 300 -63 497 88\n-- qm5          : !pos 260 33 515 89\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.STORM_ON_THE_HORIZON)\n\nquest.reward =\n{\n    item = xi.item.ICARUS_WING,\n}\n\nquest.sections =\n{\n    -- Zone into Bastok Markets [S] from North Gustaberg [S]\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BURDEN_OF_SUSPICION)\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                if\n                    quest:getVar(player, 'Prog') == 1 and\n                    prevZone == xi.zone.NORTH_GUSTABERG_S and\n                    not quest:getMustZone(player) and\n                    quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n                then\n                    return 56\n                end\n            end,\n\n            ['Blatherix'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(37)\n                    else\n                        return quest:event(38)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [37] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.ELIXIR) then\n                        quest:setVar(player, 'Prog', 1)\n                        quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                        quest:setMustZone(player)\n                    end\n                end,\n\n                [56] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    -- Gentle Tiger -> Monument -> Grauberg ??? reward/completion\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 2 then\n                        return quest:progressEvent(57)\n                    elseif questProgress == 3 then\n                        return quest:event(58)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [57] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            }\n        },\n\n        [xi.zone.NORTH_GUSTABERG_S] =\n        {\n            ['Monument'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(4)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [4] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n\n        [xi.zone.GRAUBERG_S] =\n        {\n            ['qm5'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 4 then\n                        return quest:progressEvent(16)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [16] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_BAS_6_Fire_in_the_Hole.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_BAS_6_Fire_in_the_Hole.lua",["SHA256"]="1811b83425f11cbe3881dbdeb2d8540748ed7dbe9967e5a4913187cd53eb46b7",["Text"]="-----------------------------------\n-- Fire in the Hole (WOTG Nation Quests - Bastok 6)\n-----------------------------------\n-- !addquest 7 36\n-- Stonehoused Adit : !pos -434.655 36.708 279.983 88\n-- Gentle Tiger     : !pos -203.932 -9.998 2.237 87\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.FIRE_IN_THE_HOLE)\n\nquest.reward =\n{\n    item  = xi.item.REPUBLICAN_SILVER_MEDAL,\n    title = xi.title.MYTHRIL_MUSKETEER_NO_6,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.STORM_ON_THE_HORIZON) and\n                player:getCurrentMission(xi.mission.log_id.WOTG) >= xi.mission.id.wotg.IN_THE_NAME_OF_THE_FATHER\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                if prevZone == xi.zone.NORTH_GUSTABERG_S then\n                    return 60\n                end\n            end,\n\n            onEventFinish =\n            {\n                [60] = function(player, csid, option, npc)\n                    player:startEvent(77)\n                end,\n\n                [77] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveKeyItem(player, xi.keyItem.SILVERMINE_KEY)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.NORTH_GUSTABERG_S] =\n        {\n            ['Stonehoused_Adit'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        quest:getVar(player, 'Prog') == 0 and\n                        player:hasKeyItem(xi.keyItem.SILVERMINE_KEY)\n                    then\n                        return quest:progressEvent(5)\n                    end\n                end,\n            },\n\n            ['Solitary_Ant'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if\n                        questProgress >= 0 and\n                        questProgress <= 1 and\n                        player:hasKeyItem(xi.keyItem.SILVERMINE_KEY)\n                    then\n                        return quest:progressEvent(7)\n                    elseif\n                        questProgress >= 2 and\n                        not player:hasKeyItem(xi.keyItem.SILVERMINE_KEY)\n                    then\n                        return quest:progressEvent(8)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if\n                    quest:getVar(player, 'Prog') == 3 and\n                    prevZone == xi.zone.RUHOTZ_SILVERMINES\n                then\n                    return 6\n                end\n            end,\n\n            onEventFinish =\n            {\n                [5] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [6] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                [8] = function(player, csid, option, npc)\n                    if npc and npc:getName() == 'Solitary_Ant' then\n                        npcUtil.giveKeyItem(player, xi.keyItem.SILVERMINE_KEY)\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.RUHOTZ_SILVERMINES] =\n        {\n            -- Fire in the Hole instance is not implemented currently\n            onEventFinish =\n            {\n                [10000] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        quest:setVar(player, 'Prog', 3)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                if\n                    quest:getVar(player, 'Prog') == 4 and\n                    prevZone == xi.zone.NORTH_GUSTABERG_S\n                then\n                    return 62\n                end\n            end,\n\n            ['Gentle_Tiger'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 5 then\n                        return quest:progressEvent(63)\n                    elseif questProgress == 6 then\n                        return quest:progressEvent(65)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [62] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n\n                [63] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                end,\n\n                [65] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_BAS_7_Quelling_the_Storm.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_BAS_7_Quelling_the_Storm.lua",["SHA256"]="32193f0b2b2a06fc8128d8878226108e960701d7313eae9de93a981672ea66e8",["Text"]="-----------------------------------\n-- Quelling the Storm (WOTG Nation Quests - Bastok 7)\n-----------------------------------\n-- !addquest 7 42\n-- Gentle Tiger : !pos -203.932 -9.998 2.237 87\n-- Paul         : !pos -192.880 -3.999 53.083 87\n-- Biggorf      : !pos -210.139 1.999 -140.872 87\n-- Wilhelmina   : !pos -158.092 -4.000 -120.077 87\n-- Blatherix    : !pos -309.824 -11.999 -42.791 87\n-- ??? (qm8)    : !pos -356.278 -32.117 285.950 83\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.QUELLING_THE_STORM)\n\nlocal function checkTownNpcProgress(player)\n    if\n        quest:getVar(player, 'Paul') == 1 and\n        quest:getVar(player, 'Biggorf') == 1 and\n        quest:getVar(player, 'Wilhelmina') == 1\n    then\n        quest:setVar(player, 'Prog', 2)\n    end\nend\n\nquest.reward =\n{\n    item = xi.item.GOBLIN_BELT,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.FIRE_IN_THE_HOLE) and\n                player:getCurrentMission(xi.mission.log_id.WOTG) >= xi.mission.id.wotg.CROSSROADS_OF_TIME\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                if prevZone == xi.zone.NORTH_GUSTABERG_S then\n                    return 179\n                end\n            end,\n\n            onEventFinish =\n            {\n                [179] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(180)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [180] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(186),\n\n            ['Paul'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Paul') == 0 then\n                        return quest:progressEvent(193)\n                    else\n                        return quest:event(196)\n                    end\n                end,\n            },\n\n            ['Biggorf'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Biggorf') == 0 then\n                        return quest:progressEvent(194)\n                    else\n                        return quest:event(197)\n                    end\n                end,\n            },\n\n            ['Wilhelmina'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Wilhelmina') == 0 then\n                        return quest:progressEvent(192)\n                    else\n                        return quest:event(195)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [192] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Wilhelmina', 1)\n                    checkTownNpcProgress(player)\n                end,\n\n                [193] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Paul', 1)\n                    checkTownNpcProgress(player)\n                end,\n\n                [194] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Biggorf', 1)\n                    checkTownNpcProgress(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Paul']       = quest:event(196),\n            ['Biggorf']    = quest:event(197),\n            ['Wilhelmina'] = quest:event(195),\n\n            ['Gentle_Tiger'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(181)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [181] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(187),\n\n            ['Blatherix'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(182)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [182] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 4\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(187),\n\n            ['Blatherix'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(188)\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(\n                            trade,\n                            {\n                                xi.item.GOBLIN_MESS_TIN,\n                                xi.item.GOBLIN_MUSHPOT,\n                                xi.item.PINCH_OF_TWINKLE_POWDER,\n                            }\n                        )\n                    then\n                        return quest:progressEvent(183)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [183] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 5\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Blatherix'] = quest:event(189),\n\n            ['Gentle_Tiger'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(184)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [184] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 6\n        end,\n\n        [xi.zone.VUNKERL_INLET_S] =\n        {\n            ['qm8'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(113)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [113] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 7)\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(190),\n            ['Blatherix']    = quest:event(189),\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 7\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(191),\n\n            ['Blatherix'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(185)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [185] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_BAS_8_Honor_Under_Fire.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_BAS_8_Honor_Under_Fire.lua",["SHA256"]="204dd81d6cda5b067900ec684c7554190e1cd55a6334a89c5822a1ee73859aca",["Text"]="-----------------------------------\n-- Honor Under Fire (WOTG Nation Quests - Bastok 8)\n-----------------------------------\n-- !addquest 7 43\n-- Gentle Tiger    : !pos -203.932 -9.998 2.237 87\n-- ??? (qm8)       : !pos -356.278 -32.117 285.950 83\n-- Beastman Ensign : !pos 241.000 -31.995 242.999 83\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.HONOR_UNDER_FIRE)\n\nquest.reward =\n{\n    item = xi.item.ELIXIR_TANK,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.QUELLING_THE_STORM) and\n                player:getCurrentMission(xi.mission.log_id.WOTG) >= xi.mission.id.wotg.CROSSROADS_OF_TIME\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:progressEvent(66),\n\n            onEventFinish =\n            {\n                [66] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(67),\n        },\n\n        [xi.zone.VUNKERL_INLET_S] =\n        {\n            ['qm8'] = quest:progressEvent(114),\n\n            onEventFinish =\n            {\n                [114] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(67),\n        },\n\n        [xi.zone.VUNKERL_INLET_S] =\n        {\n            ['Beastman_Ensign'] = quest:progressEvent(115),\n\n            onEventFinish =\n            {\n                [115] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:progressEvent(68),\n\n            onEventFinish =\n            {\n                [68] = function(player, csid, option, npc)\n                    if npcUtil.giveKeyItem(player, xi.keyItem.FLARE_GRENADE) then\n                        quest:setVar(player, 'Prog', 3)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(69),\n        },\n\n        [xi.zone.VUNKERL_INLET_S] =\n        {\n            ['Beastman_Ensign'] = quest:progressEvent(116),\n\n            onEventFinish =\n            {\n                [116] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 4\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.FLARE_GRENADE) then\n                        return quest:event(69)\n                    else\n                        return quest:progressEvent(70)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [70] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.FLARE_GRENADE)\n                end,\n            },\n        },\n\n        [xi.zone.EVERBLOOM_HOLLOW] =\n        {\n            onEventFinish =\n            {\n                -- Honor Under Fire instance is not implemented currently.\n                [10000] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                    player:setPos(241.000, -31.995, 242.999, 0, xi.zone.VUNKERL_INLET_S)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 5\n        end,\n\n        [xi.zone.VUNKERL_INLET_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                if prevZone == xi.zone.EVERBLOOM_HOLLOW then\n                    return 117\n                end\n            end,\n\n            onEventFinish =\n            {\n                [117] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 6\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:progressEvent(71),\n\n            onEventFinish =\n            {\n                [71] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_BAS_9_Beneath_the_Mask.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_BAS_9_Beneath_the_Mask.lua",["SHA256"]="3996cbcda8592aef5e0e167acb963540e8110b657072dd6e75bec52c3c8a5246",["Text"]="-----------------------------------\n-- Beneath the Mask (WOTG Nation Quests - Bastok 9)\n-----------------------------------\n-- !addquest 7 49\n-- Gentle Tiger : !pos -203.932 -9.998 2.237 87\n-- Red Axe      : !pos 304.627 -27.500 13.955 175\n-- Leadavox     : !pos 207.081 -31.997 315.458 83\n-- Hoarfang     : !pos -263.577 -40.757 -329.347 136\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BENEATH_THE_MASK)\n\nquest.reward =\n{\n    item = xi.item.SUPER_RERAISER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.HONOR_UNDER_FIRE) and\n                player:getCurrentMission(xi.mission.log_id.WOTG) >= xi.mission.id.wotg.FATE_IN_HAZE\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:progressEvent(345),\n\n            onEventFinish =\n            {\n                [345] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 0\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(351),\n        },\n\n        [xi.zone.BEADEAUX_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                return 1\n            end,\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 1\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:progressEvent(346),\n\n            onEventFinish =\n            {\n                [346] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 2\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(352),\n        },\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS_S] =\n        {\n            ['Red_Axe'] = quest:progressEvent(42),\n\n            onEventFinish =\n            {\n                [42] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 3\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(352),\n        },\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS_S] =\n        {\n            ['Red_Axe'] = quest:event(44),\n        },\n\n        [xi.zone.VUNKERL_INLET_S] =\n        {\n            ['Leadavox'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if npcUtil.tradeHasExactly(trade, { xi.item.LUMP_OF_BEESWAX, xi.item.JAR_OF_RED_TEXTILE_DYE }) then\n                        return quest:progressEvent(2)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    player:confirmTrade()\n\n                    if npcUtil.giveKeyItem(player, xi.keyItem.WAX_SEAL) then\n                        quest:setVar(player, 'Prog', 4)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and\n                vars.Prog == 4 and\n                player:hasKeyItem(xi.keyItem.WAX_SEAL)\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(352),\n        },\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS_S] =\n        {\n            ['Red_Axe'] = quest:progressEvent(43),\n\n            onEventFinish =\n            {\n                [43] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                    player:delKeyItem(xi.keyItem.WAX_SEAL)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 5\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:progressEvent(347),\n\n            onEventFinish =\n            {\n                [347] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                end,\n            },\n        },\n\n        [xi.zone.THE_ELDIEME_NECROPOLIS_S] =\n        {\n            ['Red_Axe'] = quest:event(45),\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED and vars.Prog == 6\n        end,\n\n        [xi.zone.BASTOK_MARKETS_S] =\n        {\n            ['Gentle_Tiger'] = quest:event(353),\n        },\n\n        [xi.zone.BEAUCEDINE_GLACIER_S] =\n        {\n            ['Hoarfang'] = quest:progressEvent(7),\n\n            onEventFinish =\n            {\n                [7] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_SAN_0_Steamed_Rams.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_SAN_0_Steamed_Rams.lua",["SHA256"]="699b2c4d7bfef5f114b1d189fba065ff4d2435567cd942840911e501d6f4e82a",["Text"]="-----------------------------------\n-- Steamed Rams (WOTG Nation Quests - San d'Oria 0)\n-----------------------------------\n-- !addquest 7 9\n-- Randecque   : !pos 61 -6 137 164\n-- Mainchelite : !pos -16 1 -30 80\n-- qm3         : !pos 312.821 -30.495 -67.15 81\n-- qm4         : !pos 541.425 -49.83 178.563 81\n-- qm5         : !pos 380.015 -26.5 -22.525 81\n-----------------------------------\nlocal southernSandoriaSID = zones[xi.zone.SOUTHERN_SAN_DORIA_S]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.STEAMED_RAMS)\n\nquest.reward =\n{\n    title = xi.title.KNIGHT_OF_THE_IRON_RAM,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.GARLAIGE_CITADEL_S] =\n        {\n            ['Randecque'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:getCampaignAllegiance() > 0 then\n                        return quest:event(12)\n                    elseif not player:hasKeyItem(xi.keyItem.RED_RECOMMENDATION_LETTER) then\n                        local hasDeclined = quest:getVar(player, 'Option')\n\n                        return quest:progressEvent(1, { [7] = hasDeclined })\n                    else\n                        return quest:progressEvent(2)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    if option == 0 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.RED_RECOMMENDATION_LETTER)\n                        quest:setVar(player, 'Option', 0)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Mainchelite'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_FIGHTING_FOURTH) == xi.questStatus.QUEST_ACCEPTED or\n                        player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.SNAKE_ON_THE_PLAINS) == xi.questStatus.QUEST_ACCEPTED\n                    then\n                        return quest:event(9)\n                    elseif\n                        player:hasKeyItem(xi.keyItem.RED_RECOMMENDATION_LETTER) or\n                        player:getCampaignAllegiance() > 0\n                    then\n                        local hasDeclined = quest:getVar(player, 'Option')\n                        local isPledged   = player:getCampaignAllegiance() > 0 and 3 or 0\n\n                        return quest:progressEvent(7 + isPledged + hasDeclined)\n                    else\n                        return quest:event(15)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [7] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                        player:delKeyItem(xi.keyItem.RED_RECOMMENDATION_LETTER)\n                    else\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n\n                [8] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                        player:delKeyItem(xi.keyItem.RED_RECOMMENDATION_LETTER)\n                    end\n                end,\n\n                [10] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    else\n                        quest:setVar(player, 'Option', 1)\n                    end\n                end,\n\n                [11] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Mainchelite'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.CHARRED_PROPELLER) and\n                        player:hasKeyItem(xi.keyItem.OXIDIZED_PLATE) and\n                        player:hasKeyItem(xi.keyItem.PIECE_OF_SHATTERED_LUMBER)\n                    then\n                        if player:getCampaignAllegiance() == 0 then\n                            return quest:progressEvent(12)\n                        else\n                            return quest:progressEvent(624)\n                        end\n                    else\n                        local isPledged = player:getCampaignAllegiance() > 0 and 1 or 0\n\n                        return quest:progressEvent(13 + isPledged)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [12] = function(player, csid, option, npc)\n                    local hasNoAllegiance = player:getCampaignAllegiance() == 0\n\n                    if\n                        hasNoAllegiance and\n                        not npcUtil.giveItem(player, xi.item.SPRINTERS_SHOES)\n                    then\n                        return\n                    end\n\n                    if quest:complete(player) then\n                        if hasNoAllegiance then\n                            npcUtil.giveKeyItem(player, xi.keyItem.BRONZE_RIBBON_OF_SERVICE)\n                        end\n\n                        player:setCampaignAllegiance(1)\n\n                        player:delKeyItem(xi.keyItem.CHARRED_PROPELLER)\n                        player:delKeyItem(xi.keyItem.OXIDIZED_PLATE)\n                        player:delKeyItem(xi.keyItem.PIECE_OF_SHATTERED_LUMBER)\n\n                        player:messageSpecial(southernSandoriaSID.text.NOW_ALLIED_WITH, 1)\n                    end\n                end,\n\n                [13] = function(player, csid, option, npc)\n                    if option == 1 then\n                        npcUtil.giveKeyItem(player, xi.keyItem.RED_RECOMMENDATION_LETTER)\n                        player:delQuest(quest.areaId, quest.questId)\n                    end\n                end,\n\n                [14] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:delQuest(quest.areaId, quest.questId)\n                    end\n                end,\n\n                [624] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        -- TODO: Adjust medal count for allegiance change.\n\n                        player:setCampaignAllegiance(1)\n\n                        player:delKeyItem(xi.keyItem.CHARRED_PROPELLER)\n                        player:delKeyItem(xi.keyItem.OXIDIZED_PLATE)\n                        player:delKeyItem(xi.keyItem.PIECE_OF_SHATTERED_LUMBER)\n\n                        player:messageSpecial(southernSandoriaSID.text.NOW_ALLIED_WITH, 1)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.EAST_RONFAURE_S] =\n        {\n            ['qm3'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.CHARRED_PROPELLER) then\n                        return quest:progressEvent(1)\n                    end\n                end,\n            },\n\n            ['qm4'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.PIECE_OF_SHATTERED_LUMBER) then\n                        return quest:progressEvent(2)\n                    end\n                end,\n            },\n\n            ['qm5'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.OXIDIZED_PLATE) then\n                        return quest:progressEvent(3)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.CHARRED_PROPELLER)\n                end,\n\n                [2] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.PIECE_OF_SHATTERED_LUMBER)\n                end,\n\n                [3] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.OXIDIZED_PLATE)\n                end,\n            },\n\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Mainchelite'] = quest:event(5):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_SAN_10_Blood_of_Heroes.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_SAN_10_Blood_of_Heroes.lua",["SHA256"]="f62611b8672231e8d9347bb09d3e8855d157ec90c940e24afe3219606435a412",["Text"]="-----------------------------------\n-- Blood of Heroes (WOTG Nation Quests - San d'Oria 10)\n-----------------------------------\n-- !addquest 7 52\n-- Animal Spoor      : !pos 543.954 -0.522 -290.313 137\n-- Wheel Rut         : !pos 345.162 -0.743 -309.161 137\n-- Forbidding Portal : !pos 320 -10.835 158.699 137\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BLOOD_OF_HEROES)\n\nquest.reward =\n{\n    item  = xi.item.RAM_STAFF,\n    title = xi.title.HOUSE_AURCHIAT_RETAINER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.SONGBIRDS_IN_A_SNOWSTORM)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rholont'] = quest:event(656),\n        },\n\n        [xi.zone.XARCABARD_S] =\n        {\n            ['Animal_Spoor'] = quest:progressEvent(1),\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.XARCABARD_S] =\n        {\n            ['Animal_Spoor'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:progressEvent(3)\n                    elseif\n                        questProgress == 3 and\n                        not player:hasKeyItem(xi.keyItem.VIAL_OF_MILITARY_PRISM_POWDER)\n                    then\n                        -- NOTE: Upon implementation of the instance for this quest, on instance failure will\n                        -- need to set the 'Timer' charVar to VanadielUniqueDay() + 1\n\n                        if quest:getVar(player, 'Timer') <= VanadielUniqueDay() then\n                            return quest:progressEvent(13)\n                        else\n                            return quest:event(15)\n                        end\n                    end\n                end,\n            },\n\n            ['Forbidding_Portal'] =\n            {\n                onTrigger = function(player, npc)\n                    -- TODO: Instance entry should require questProgress of 3, along with a Vial of Military Prism\n                    -- Powder.  Instance is accessed from this NPC with Event 12, param (0, 0, 52)\n\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(4)\n                    end\n                end,\n            },\n\n            ['Wheel_Rut'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(2)\n                    elseif questProgress == 5 then\n                        return quest:progressEvent(7)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 4 then\n                    return 6\n                end\n            end,\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [3] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.VIAL_OF_MILITARY_PRISM_POWDER)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [4] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [6] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n\n                [7] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.quest.setVar(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.CHASING_SHADOWS, VanadielUniqueDay() + 1)\n                    end\n                end,\n\n                [13] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.VIAL_OF_MILITARY_PRISM_POWDER)\n                end,\n            },\n        },\n\n        [xi.zone.GHOYUS_REVERIE] =\n        {\n            onEventFinish =\n            {\n                [10000] = function(player, csid, option, npc)\n                    -- TODO: The assumption for this mission script is to catch Event 10000 which is\n                    -- sent once the battlefield has been cleared.  This needs to be verified upon\n                    -- implementation of the instance.\n\n                    quest:setVar(player, 'Prog', 4)\n                    player:setPos(319.8, -7.887, 153.741, 65, xi.zone.XARCABARD_S)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_SAN_11_Chasing_Shadows.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_SAN_11_Chasing_Shadows.lua",["SHA256"]="a6fb078ed05f0e84561f48d852d61340f99208554d8a849adde3aa6e1f9caec8",["Text"]="-----------------------------------\n-- Chasing Shadows (WOTG Nation Quests - San d'Oria 11)\n-----------------------------------\n-- !addquest 7 60\n-- Rongelouts        : !pos 0.067 2 -22 80\n-- Backfilled Pit    : !pos -172 -2.818 -85 137\n-- Compact Footprint : !pos 242.145 -15.42 -147.417 137\n-- Sunken Footprint  : !pos 188.429 -27.623 163.764 137\n-- Fresh Snowmelt    : !pos -71.660 -2.58 450.114 84\n-----------------------------------\nlocal pastBatalliaID = zones[xi.zone.BATALLIA_DOWNS_S]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.CHASING_SHADOWS)\n\nquest.reward =\n{\n    item = xi.item.DARKSTEEL_SHEET,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BLOOD_OF_HEROES) and\n                quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rholont']              = quest:event(656),\n            ['Rongelouts_N_Distaud'] = quest:progressEvent(165),\n\n            onEventFinish =\n            {\n                [165] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rholont']              = quest:event(167),\n            ['Rongelouts_N_Distaud'] = quest:event(168),\n        },\n\n        [xi.zone.XARCABARD_S] =\n        {\n            ['Backfilled_Pit'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(31)\n                    end\n                end,\n            },\n\n            ['Compact_Footprint'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 2 then\n                        return quest:progressEvent(32)\n                    elseif questProgress == 4 then\n                        return quest:progressEvent(34)\n                    end\n                end,\n            },\n\n            ['Sunken_Footprint'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(33)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.BEAUCEDINE_GLACIER_S and\n                    quest:getVar(player, 'Prog') == 0\n                then\n                    return 30\n                end\n            end,\n\n            onEventFinish =\n            {\n                [30] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [31] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [32] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [33] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                [34] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n\n        [xi.zone.BATALLIA_DOWNS_S] =\n        {\n            ['Fresh_Snowmelt'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 6 then\n                        return quest:progressEvent(115)\n                    elseif\n                        questProgress == 7 and\n                        not GetMobByID(pastBatalliaID.mob.MENECHME):isSpawned()\n                    then\n                        -- TODO: Menechme has been set to Level 150 until proper data is obtained, and\n                        -- Excenmille assists in this fight who is currently set to level 0 and not spawned\n                        -- at this time.  Menecheme by default will approach Excenmille and attack.\n\n                        return quest:progressEvent(116)\n                    elseif questProgress == 8 then\n                        return quest:progressEvent(117)\n                    end\n                end,\n            },\n\n            ['Menechme'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 7 then\n                        quest:setVar(player, 'Prog', 8)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.BEAUCEDINE_GLACIER_S and\n                    quest:getVar(player, 'Prog') == 5\n                then\n                    return 114\n                end\n            end,\n\n            onEventFinish =\n            {\n                [114] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                end,\n\n                [115] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 7)\n                end,\n\n                [116] = function(player, csid, option, npc)\n                    SpawnMob(pastBatalliaID.mob.MENECHME)\n                end,\n\n                [117] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:addQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.FACE_OF_THE_FUTURE)\n                        player:setPos(-49.903, 0.293, 436.922, 0, xi.zone.BATALLIA_DOWNS)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_SAN_12_Face_of_the_Future.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_SAN_12_Face_of_the_Future.lua",["SHA256"]="d1a6d378e4840c47747e8d8084e8836fffa660ae9966b47350e87fcc70349265",["Text"]="-----------------------------------\n-- Face of the Future (WOTG Nation Quests - San d'Oria 12)\n-----------------------------------\n-- !addquest 7 61\n-- Metallic Hodgepodge : !pos -285.493 -7.819 -163.707 104\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.FACE_OF_THE_FUTURE)\n\nquest.reward =\n{\n    item  = xi.item.GRIFFON_RING,\n    title = xi.title.FANGMONGER_FORESTALLER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.JUGNER_FOREST] =\n        {\n            ['Metallic_Hodgepodge'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(45)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.BATALLIA_DOWNS and\n                    quest:getVar(player, 'Prog') == 0\n                then\n                    return 44\n                end\n            end,\n\n            onEventFinish =\n            {\n                [44] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [45] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.GHELSBA_OUTPOST] =\n        {\n            ['Clandestine_Marking'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.ORCISH_INFILTRATION_KIT) then\n                        return quest:keyItem(xi.keyItem.ORCISH_INFILTRATION_KIT)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 2 then\n                    return 57\n                end\n            end,\n\n            onEventFinish =\n            {\n                [57] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.YUGHOTT_GROTTO] =\n        {\n            ['Scrape_Mark'] =\n            {\n                onTrigger = function(player, npc)\n                    -- NOTE: Progress of 4 is required for instance entry.  Followup event to\n                    -- register for the instance is Event 103, Params: 0, 0, 61\n\n                    if quest:getVar(player , 'Prog') == 3 then\n                        return quest:progressEvent(1)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 5 then\n                    return 2\n                end\n            end,\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                [2] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                    player:setPos(13.29, -0.104, -59.417, 253, xi.zone.GHELSBA_OUTPOST)\n                end,\n            },\n        },\n\n        [xi.zone.EVERBLOOM_HOLLOW] =\n        {\n            onEventFinish =\n            {\n                [10000] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                    player:setPos(-184.678, -0.266, -112.093, 101, xi.zone.YUGHOTT_GROTTO)\n                end,\n            },\n        },\n\n        [xi.zone.BATALLIA_DOWNS] =\n        {\n            ['Cavernous_Maw'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        xi.maws.hasUnlockedMaw(player, xi.zone.BATALLIA_DOWNS) and\n                        quest:getVar(player, 'Prog') == 6\n                    then\n                        return quest:progressEvent(504)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                local questProgress = quest:getVar(player, 'Prog')\n\n                if questProgress == 7 then\n                    return 505\n                elseif questProgress == 9 then\n                    return 508\n                elseif questProgress == 10 then\n                    return 507\n                end\n            end,\n\n            onEventFinish =\n            {\n                [504] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 7)\n                    player:setPos(-47.108, 0.153, 437.1, 65, xi.zone.BATALLIA_DOWNS)\n                end,\n\n                [505] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 8)\n\n                    -- TODO: This location is assumed from previous captures, and is most likely\n                    -- not accurate.  While sufficient to proceed, this needs to be updated.\n                    player:setPos(-105.798, -25.522, -53.499, 176, xi.zone.XARCABARD_S)\n                end,\n\n                [507] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:setPos(-49.368, 0.268, 436.691, 252, xi.zone.BATALLIA_DOWNS_S)\n                    end\n                end,\n\n                [508] = function(player, csid, option, npc)\n                    -- TODO: This location is assumed from previous captures, and is most likely\n                    -- not accurate.  While sufficient to proceed, this needs to be updated.\n\n                    quest:setVar(player, 'Prog', 10)\n                    player:setPos(-47.108, 0.154, 437.1, 65, xi.zone.BATALLIA_DOWNS)\n                end,\n            },\n        },\n\n        [xi.zone.XARCABARD_S] =\n        {\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 8 then\n                    return 40\n                end\n            end,\n\n            onEventFinish =\n            {\n                [40] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 9)\n                    player:setPos(-47.108, 0.154, 437.1, 65, xi.zone.BATALLIA_DOWNS)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_SAN_1_Gifts_of_the_Griffon.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_SAN_1_Gifts_of_the_Griffon.lua",["SHA256"]="10813dbeefd9778020f2ae99556fece856cece825af9be565b998b1ef08668fb",["Text"]="-----------------------------------\n-- Gifts of the Griffon (WOTG Nation Quests - San d'Oria 1)\n-----------------------------------\n-- !addquest 7 15\n-- Louxiard   : !pos -93 -4 49 80\n-- Rholont    : !pos -168 -2 56 80\n-- Elnonde    : !pos 86 2 -0 80\n-- Illeuse    : !pos -44.203 2 -36.216 80\n-- Loillie    : !pos 78 -8 -23 80\n-- Machionage : !pos -255 -3 109 80\n-- Rongelouts : !pos 0.067 2 -22 80\n-- Sabiliont  : !pos 9 2 -87 80\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.GIFTS_OF_THE_GRIFFON)\n\nquest.reward =\n{\n    item = xi.item.DEATHSTONE,\n}\n\nlocal npcTradeEvents =\n{\n    ['Elnonde']              = 30,\n    ['Illeuse']              = 31,\n    ['Loillie']              = 29,\n    ['Louxiard']             = 26,\n    ['Machionage']           = 28,\n    ['Rongelouts_N_Distaud'] = 25,\n    ['Sabiliont']            = 27,\n}\n\nlocal plumeTradeNpc =\n{\n    onTrade = function(player, npc, trade)\n        local tradeEventId = npcTradeEvents[npc:getName()]\n\n        if\n            npcUtil.tradeHasExactly(trade, xi.item.PLUME_DOR) and\n            not quest:isVarBitsSet(player, 'Option', tradeEventId - 25)\n        then\n            return quest:progressEvent(tradeEventId)\n        end\n    end,\n}\n\nlocal plumeOnEventFinish = function(player, csid, option, npc)\n    player:confirmTrade()\n    quest:setVarBit(player, 'Option', csid - 25)\nend\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.wotg.helpers.hasCompletedFirstQuest(player)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Louxiard'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(21)\n                    elseif\n                        questProgress == 1 and\n                        not quest:getMustZone(player)\n                    then\n                        return quest:progressEvent(22)\n                    end\n                end,\n            },\n\n            ['Rholont'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 2 then\n                        return quest:progressEvent(23)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [21] = function(player, csid, option, npc)\n                    quest:setMustZone(player)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [22] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [23] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    npcUtil.giveItem(player, { { xi.item.PLUME_DOR, 7 } })\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rholont'] =\n            {\n                onTrigger = function(player, npc)\n                    local plumesTraded = utils.mask.countBits(quest:getVar(player, 'Option'), 7)\n\n                    if\n                        not player:hasItem(xi.item.PLUME_DOR) and\n                        plumesTraded < 7\n                    then\n                        local waitTime = quest:getVar(player, 'Timer')\n\n                        if waitTime == 0 then\n                            return quest:progressEvent(34)\n                        elseif GetSystemTime() < waitTime then\n                            return quest:event(46)\n                        else\n                            return quest:progressEvent(35)\n                        end\n                    elseif plumesTraded == 7 then\n                        return quest:progressEvent(24)\n                    else\n                        return quest:event(33)\n                    end\n                end,\n            },\n\n            ['Elnonde']              = plumeTradeNpc,\n            ['Illeuse']              = plumeTradeNpc,\n            ['Loillie']              = plumeTradeNpc,\n            ['Louxiard']             = plumeTradeNpc,\n            ['Machionage']           = plumeTradeNpc,\n            ['Rongelouts_N_Distaud'] = plumeTradeNpc,\n            ['Sabiliont']            = plumeTradeNpc,\n\n            onEventFinish =\n            {\n                [24] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.quest.setVar(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.CLAWS_OF_THE_GRIFFON, 'Timer', VanadielUniqueDay() + 1)\n                    end\n                end,\n\n                [25] = plumeOnEventFinish,\n                [26] = plumeOnEventFinish,\n                [27] = plumeOnEventFinish,\n                [28] = plumeOnEventFinish,\n                [29] = plumeOnEventFinish,\n                [30] = plumeOnEventFinish,\n                [31] = plumeOnEventFinish,\n\n                [34] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Timer', NextConquestTally())\n                end,\n\n                [35] = function(player, csid, option, npc)\n                    local numPlumes = 7 - utils.mask.countBits(quest:getVar(player, 'Option'), 7)\n\n                    quest:setVar(player, 'Timer', 0)\n                    npcUtil.giveItem(player, { { xi.item.PLUME_DOR, numPlumes } })\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_SAN_2_Claws_of_the_Griffon.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_SAN_2_Claws_of_the_Griffon.lua",["SHA256"]="3fd10dd88720af23031209c895d3c0baf087a05f5400183fe4bb3d57bff24e3f",["Text"]="-----------------------------------\n-- Claws of the Griffon (WOTG Nation Quests - San d'Oria 2)\n-----------------------------------\n-- !addquest 7 15\n-- Rholont : !pos -168 -2 56 80\n-- qm6     : !pos 68 -0.5 324 82\n-----------------------------------\nlocal jugnerSID = zones[xi.zone.JUGNER_FOREST_S]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.CLAWS_OF_THE_GRIFFON)\n\nquest.reward =\n{\n    item = xi.item.ANGELSTONE,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.GIFTS_OF_THE_GRIFFON)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n\n            ['Rholont'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Timer') <= VanadielUniqueDay() then\n                        return quest:progressEvent(47)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [47] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    quest:setMustZone(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rholont'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not quest:getMustZone(player) and\n                        quest:getVar(player, 'Prog') == 0\n                    then\n                        return quest:progressEvent(48)\n                    else\n                        local questOption = quest:getVar(player, 'Option')\n\n                        if questOption == 0 then\n                            return quest:progressEvent(50)\n                        else\n                            return quest:event(49)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [48] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [50] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n            },\n        },\n\n        [xi.zone.JUGNER_FOREST_S] =\n        {\n            ['qm6'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 2 then\n                        return quest:progressEvent(201)\n                    elseif\n                        questProgress == 3 and\n                        not GetMobByID(jugnerSID.mob.FINGERFILCHER_DRADZAD):isSpawned()\n                    then\n                        return quest:progressEvent(202)\n                    elseif questProgress == 4 then\n                        return quest:progressEvent(203)\n                    end\n                end,\n            },\n\n            ['Fingerfilcher_Dradzad'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        quest:setVar(player, 'Prog', 4)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.EAST_RONFAURE_S and\n                    quest:getVar(player, 'Prog') == 1\n                then\n                    return 200\n                end\n            end,\n\n            onEventFinish =\n            {\n                [200] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [201] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [202] = function(player, csid, option, npc)\n                    SpawnMob(jugnerSID.mob.FINGERFILCHER_DRADZAD):updateClaim(player)\n                end,\n\n                [203] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_SAN_3_Boy_and_the_Beast.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_SAN_3_Boy_and_the_Beast.lua",["SHA256"]="368dcb843c329ca77a83e261f83069a386b86bb5230453b42ccb4ca3234ac983",["Text"]="-----------------------------------\n-- Boy and the Beast (WOTG Nation Quests - San d'Oria 3)\n-----------------------------------\n-- !addquest 7 24\n-- Rholont     : !pos -168 -2 56 80\n-- qm7         : !pos -26 -31 364 83\n-- Leafy Patch : !pos -418 -33 576 83\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BOY_AND_THE_BEAST)\n\nquest.reward =\n{\n    item = xi.item.CARBON_FISHING_ROD,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedMission(xi.mission.log_id.WOTG, xi.mission.id.wotg.BACK_TO_THE_BEGINNING) and -- WotG mission requirement.\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.CLAWS_OF_THE_GRIFFON)   -- WotG nation quest requirement.\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Raustigne'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(55)\n                    end\n                end,\n            },\n\n            ['Rholont'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:progressEvent(56)\n                    elseif questProgress == 2 then\n                        return quest:event(57)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [55] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [56] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.VUNKERL_INLET_S] =\n        {\n            ['qm7'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(105)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [105] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.VUNKERL_HERB_MEMO)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.VUNKERL_INLET_S] =\n        {\n            ['qm7'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.VUNKERL_HERB) then\n                        if quest:getVar(player, 'Prog') == 3 then\n                            return quest:progressEvent(108)\n                        else\n                            return quest:progressEvent(109)\n                        end\n                    else\n                        -- NOTE: The below two events are \"Nothing out of the Ordinary\" events; however, Event 110\n                        -- is only displayed the first time in this state.  Unknown use at this time, but implemented\n                        -- for accuracy.  This Option var is actually reset every time a different event from this\n                        -- point fires.\n\n                        if quest:getVar(player, 'Option') == 0 then\n                            return quest:event(110)\n                        else\n                            return quest:event(111)\n                        end\n                    end\n                end,\n            },\n\n            ['Leafy_Patch'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.VUNKERL_HERB) then\n                        local vanadielHour = VanadielHour()\n                        local hourParam = 0\n\n                        if vanadielHour >= 16 then\n                            hourParam = 2\n                        elseif vanadielHour >= 8 then\n                            hourParam = 1\n                        end\n\n                        return quest:progressEvent(107, hourParam)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [107] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Prog', 3)\n                    end\n\n                    npcUtil.giveKeyItem(player, xi.keyItem.VUNKERL_HERB)\n                end,\n\n                [108] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.VUNKERL_HERB)\n                        player:delKeyItem(xi.keyItem.VUNKERL_HERB_MEMO)\n                    end\n                end,\n\n                [109] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.VUNKERL_HERB)\n                end,\n\n                [110] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_SAN_4_Wrath_of_the_Griffon.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_SAN_4_Wrath_of_the_Griffon.lua",["SHA256"]="fe3176f1d892306a4e86b155fb1d859b69ebbcf0b4765f89cfb45dfaf87e29c9",["Text"]="-----------------------------------\n-- Wrath of the Griffon (WOTG Nation Quests - San d'Oria 4)\n-----------------------------------\n-- !addquest 7 25\n-- Rholont : !pos -168 -2 56 80\n-- qm8     : !pos -6 0 -295 82\n-- Wyatt   : !pos 124 0 84 80\n-----------------------------------\nlocal jugnerSID = zones[xi.zone.JUGNER_FOREST_S]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.WRATH_OF_THE_GRIFFON)\n\nquest.reward =\n{\n    keyItem = xi.keyItem.MILITARY_SCRIP,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BOY_AND_THE_BEAST)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rholont'] = quest:progressEvent(59),\n\n            onEventFinish =\n            {\n                [59] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rholont'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') < 3 then\n                        return quest:event(61)\n                    else\n                        return quest:progressEvent(60)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [60] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        xi.quest.setVar(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.PERILS_OF_THE_GRIFFON, 'Timer', VanadielUniqueDay() + 1)\n                        xi.quest.setMustZone(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.PERILS_OF_THE_GRIFFON)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.JUGNER_FOREST_S] =\n        {\n            ['qm8'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(204)\n                    elseif\n                        questProgress == 1 and\n                        not GetMobByID(jugnerSID.mob.COBRACLAW_BUCHZVOTCH):isSpawned()\n                    then\n                        return quest:progressEvent(205)\n                    elseif questProgress == 2 then\n                        return quest:progressEvent(206)\n                    end\n                end,\n            },\n\n            ['Cobraclaw_Buchzvotch'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        quest:setVar(player, 'Prog', 2)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [204] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [205] = function(player, csid, option, npc)\n                    SpawnMob(jugnerSID.mob.COBRACLAW_BUCHZVOTCH):updateClaim(player)\n                end,\n\n                [206] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED and\n                player:hasKeyItem(xi.keyItem.MILITARY_SCRIP)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Wyatt'] = quest:progressEvent(66):setPriority(1005),\n\n            onEventFinish =\n            {\n                [66] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.MILITARY_SCRIP)\n                    npcUtil.giveCurrency(player, 'gil', 20147)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"}};
